var SC=window.SugarCube||SugarCube;
var st=SC.State, setup=SC.setup;
var out={passage: st.passage};
try {
  var gh = setup.getGlobalHints ? setup.getGlobalHints() : 'NO_FN';
  out.globalHints = (gh||[]).map(function(x){return {text:(x.text||'').slice(0,55), tip:(x.tip||'').slice(0,40), acf:x.arc_closure_flag, cond:JSON.stringify(x.condition||x.conditions||null).slice(0,90)};});
} catch(e){ out.ghErr=String(e); }
return JSON.stringify(out,null,1);

var SC=window.SugarCube||SugarCube, setup=SC.setup, V=SC.State.variables;
function flags(){return (V.player&&V.player.flags)||V.flags||{};}
function ghTexts(){return (setup.getGlobalHints()||[]).map(function(x){return (x.text||'').slice(0,32);});}
var R={};
R.t0_cards = ghTexts();
// helper eval fn discovery
R.helperFns = Object.keys(setup).filter(function(k){return /helper|stage/i.test(k);}).slice(0,12);
// --- Ryan decouple: set trust=10, leave group_settled_in false ---
try{
  var ryan=(V.npcs&&V.npcs.npc_ryan)||(V.npc&&V.npc.npc_ryan);
  if(ryan){ryan.trust=10;}
  R.ryan_trust=ryan?ryan.trust:'NO_RYAN';
  var hv=null;
  if(setup.checkStageHelper) hv=setup.checkStageHelper('ryan_stage_1');
  else if(setup.evaluateStageHelper) hv=setup.evaluateStageHelper('ryan_stage_1');
  else if(setup.stageHelper) hv=setup.stageHelper('ryan_stage_1');
  R.ryan_stage_1_with_trust10_noSettled = hv;
}catch(e){R.ryanErr=String(e);}
// --- Church resolves on first_sunday_passed (stay-home, attended NOT set) ---
var f=flags(); f.first_sunday_passed=true;
R.after_sunday_only = ghTexts();
// --- Settle-in completes when transition fires (group_settled_in set) ---
f.group_settled_in=true;
R.after_settled = ghTexts();
return JSON.stringify(R,null,1);
